async def insert_hour(
    executor: edgedb.AsyncIOExecutor,
    *,
    id: list[uuid.UUID],
) -> InsertHourResult:
    return await executor.query_single(
        """\
        insert Hour {
          sub_groups := (
            select SubGroupHour
            filter .id in array_unpack(<array<uuid>>$id)
          )
        }\
        """,
        id=id,
    )


async def insert_or_select_cabinet(
    executor: edgedb.AsyncIOExecutor,
    *,
    name: str,
    room: str,
) -> DeleteCabinetResult:
    return await executor.query_single(
        """\
        insert Cabinet {
          name := <str>$name,
          room := <str>$room
        } unless conflict on .room else Cabinet;\
        """,
        name=name,
        room=room,
    )


async def insert_subgroup_hour(
    executor: edgedb.AsyncIOExecutor,
    *,
    cabinet_id: uuid.UUID,
    occupation: str,
) -> InsertSubgroupHourResult:
    return await executor.query_single(
        """\
        insert SubGroupHour {
          cabinet := (select Cabinet filter .id = <uuid>$cabinet_id),
          occupation := <str>$occupation
        };\
        """,
        cabinet_id=cabinet_id,
        occupation=occupation,
    )


